from torchvision.datasets.folder import default_loader, pil_loader
from PIL import Image

def safe_loader(path):
    try:
        return default_loader(path)
    except (OSError, Image.UnidentifiedImageError, Exception):
        return None

def custom_loader(path):
    try:
        img = pil_loader(path)
        return img
    except (OSError, Image.UnidentifiedImageError, Exception) as e:
        # Skip corrupted images
        raise FileNotFoundError(f"Cannot load image {path}: {e}")

